# ash_pplan.gen.workflow). Do not hand-edit; edit the ontology facts and re-render:
#   mix ggen_igniter.sync --pack-dir priv/ggen/ash-pplan-igniter-pack \
#     --template templates/gen_workflow_task.ex.eex --out lib/mix/tasks/ash_pplan.gen.workflow.ex
defmodule Mix.Tasks.AshPplan.Gen.Workflow do
  @shortdoc "Scaffolds a P-PLAN workflow module and semantically edits its provider selection"
  @moduledoc """

  Scaffolds a P-PLAN workflow module for ash_pplan and, with `--add-provider`,
  semantically MODIFIES an existing workflow module's provider selection map
  through Sourceror AST rewriting (never string append).

  Scaffold mode composes existing Igniter tasks: when `--with-resource` is
  given, `Igniter.compose_task(igniter, "ash.gen.resource", [module])` runs
  first, then the workflow module is generated with Igniter's AST helpers.

  """

  use Igniter.Mix.Task

  @example "mix ash_pplan.gen.workflow etl --goal \"Ingest then publish\" --providers file,network"

  @impl Igniter.Mix.Task
  def info(_argv, _composing_task) do
    %Igniter.Mix.Task.Info{
      group: :ash_pplan,
      example: @example,
      positional: [workflow: [optional: false]],
      schema: [
        add_provider: :string,
        goal: :string,
        providers: :string,
        with_resource: :string
      ],
      aliases: [y: :yes],
      required: []
    }
  end

  @impl Igniter.Mix.Task
  def igniter(igniter) do
    options = igniter.args.options
    name = igniter.args.positional[:workflow]

    cond do
      is_nil(name) ->
        Igniter.add_issue(
          igniter,
          "a workflow name is required (mix ash_pplan.gen.workflow NAME ...)"
        )

      options[:add_provider] != nil and options[:with_resource] != nil ->
        Igniter.add_issue(
          igniter,
          "--add-provider and --with-resource are mutually exclusive"
        )

      options[:add_provider] != nil ->
        add_provider(igniter, name, to_string(options[:add_provider]))

      true ->
        scaffold(igniter, name, options)
    end
    |> with_goal_warning(options)
  end

  # Scaffold mode: generate the workflow module (a Model literal plus a provider
  # selection map) with Igniter's AST helpers; compose ash.gen.resource first
  # when --with-resource is given (Igniter.compose_task/4, the lawful reuse of
  # an existing generator).
  defp scaffold(igniter, name, options) do
    camel = camel(name)
    target = Igniter.Project.Module.module_name(igniter, "Workflows." <> camel)

    igniter =
      if options[:with_resource] do
        Igniter.compose_task(igniter, "ash.gen.resource", [to_string(options[:with_resource])])
      else
        igniter
      end

    contents =
      workflow_source(name, options)

    igniter
    |> Igniter.Project.Module.create_module(target, contents)
    |> Igniter.add_warning("Generated #{inspect(target)}")
  end

  # --add-provider mode: semantically MODIFIES the existing workflow module by
  # rewriting the attribute literals as AST (Sourceror parse, zipper traverse,
  # to_string) -- never string append.
  defp add_provider(igniter, name, provider) do
    target = Igniter.Project.Module.module_name(igniter, "Workflows." <> camel(name))

    case module_path(igniter, target) do
      {:ok, path} ->
        igniter
        |> Igniter.include_existing_file(path)
        |> Igniter.update_file(path, fn source ->
          content = Rewrite.Source.get(source, :content)
          tree = Sourceror.parse_string!(content)
          modified = modify_tree!(tree, String.to_atom(provider))
          Rewrite.Source.update(source, :content, Sourceror.to_string(modified))
        end)

      :error ->
        Igniter.add_issue(
          igniter,
          "no workflow module #{inspect(target)} found; scaffold it first with " <>
            "mix ash_pplan.gen.workflow #{name}"
        )
    end
  end

  defp module_path(igniter, target) do
    path = Igniter.Project.Module.proper_location(igniter, target)
    if Igniter.exists?(igniter, path), do: {:ok, path}, else: :error
  end

  # Rewrites BOTH attribute literals as AST: `@providers [...]` gets the new
  # provider prepended (deduped) and every list value in the `@selection` map
  # gets it appended (deduped). Typed refusal when either literal is missing or
  # the wrong shape (wrong shape = wrong subject). Plain recursive AST rewrite:
  # no string append anywhere.
  defp modify_tree!(tree, provider) do
    {tree, providers_seen, selection_seen} =
      tree
      |> List.wrap()
      |> rewrite_nodes(provider, false, false)

    unless providers_seen do
      raise ArgumentError,
            "REFUSED(ADD_PROVIDER_NO_PROVIDERS_LITERAL): no `@providers [...]` literal"
    end

    unless selection_seen do
      raise ArgumentError,
            "REFUSED(ADD_PROVIDER_NO_SELECTION_LITERAL): no `@selection %{...}` literal"
    end

    tree
  end

  defp rewrite_nodes(nodes, provider, ps, ss) when is_list(nodes) do
    {nodes, {ps, ss}} =
      Enum.map_reduce(nodes, {ps, ss}, fn node, {ps, ss} ->
        {new_node, ps, ss} = rewrite_node(node, provider, ps, ss)
        {new_node, {ps, ss}}
      end)

    {nodes, ps, ss}
  end

  defp rewrite_node({:@, meta, [{:providers, ameta, [value]}]} = node, provider, ps, ss) do
    case attr_list(value) do
      {:ok, bmeta, list} ->
        new_value = {:__block__, bmeta, [Enum.uniq([{:__block__, [], [provider]} | list])]}
        {{:@, meta, [{:providers, ameta, [new_value]}]}, true, ss}

      :error ->
        {node, ps, ss}
    end
  end

  defp rewrite_node({:@, meta, [{:selection, smeta, [value]}]} = node, provider, ps, ss) do
    case attr_map(value) do
      {:ok, bmeta, mmeta, pairs} ->
        new_pairs =
          Enum.map(pairs, fn {key, value} ->
            existing =
              case value do
                {:__block__, _, [list]} when is_list(list) -> list
                list when is_list(list) -> list
                _ -> []
              end

            {key, Enum.uniq(existing ++ [{:__block__, [], [provider]}])}
          end)

        new_value =
          if bmeta do
            {:__block__, bmeta, [{:%{}, mmeta, new_pairs}]}
          else
            {:%{}, mmeta, new_pairs}
          end

        {{:@, meta, [{:selection, smeta, [new_value]}]}, ps, true}

      :error ->
        {node, ps, ss}
    end
  end

  defp rewrite_node(node, provider, ps, ss) when is_tuple(node) do
    {children, ps, ss} = rewrite_nodes(Tuple.to_list(node), provider, ps, ss)
    {List.to_tuple(children), ps, ss}
  end

  defp rewrite_node(nodes, provider, ps, ss) when is_list(nodes) do
    rewrite_nodes(nodes, provider, ps, ss)
  end

  defp rewrite_node(node, _provider, ps, ss), do: {node, ps, ss}

  # `@providers [...]`: the value is a __block__-wrapped list of nodes.
  defp attr_list({:__block__, meta, [list]}) when is_list(list), do: {:ok, meta, list}
  defp attr_list(_), do: :error

  # `@selection %{...}`: the value may or may not be __block__-wrapped.
  defp attr_map({:__block__, meta, [{:%{}, mmeta, pairs}]}), do: {:ok, meta, mmeta, pairs}
  defp attr_map({:%{}, mmeta, pairs}), do: {:ok, nil, mmeta, pairs}
  defp attr_map(_), do: :error
  # Scaffold content: an AshPPlan.Workflow.Model literal plus a provider
  # selection map, both as code the --add-provider pass can rewrite.
  defp workflow_source(name, options) do
    goal = options[:goal] || "TODO: describe the goal"
    providers = parse_providers(options[:providers])

    """
    @moduledoc "Scaffolded P-PLAN workflow `#{name}` (mix ash_pplan.gen.workflow). Regenerate or extend with --add-provider."

      alias AshPPlan.Workflow.Model

      @providers #{inspect(providers)}
      @selection %{"start" => #{inspect(providers)}}

      @spec model() :: {:ok, Model.t()} | {:error, map()}
      def model do
        Model.new(
          name: "#{name}",
          goal: #{inspect(goal)},
          tasks: [
            %{
              id: "start",
              capability: "Domain.Read",
              outcomes: [:ok],
              terminal_outcomes: [:ok]
            }
          ]
        )
      end

      @spec providers() :: [atom()]
      def providers, do: @providers

      @spec selection() :: %{String.t() => [atom()]}
      def selection, do: @selection
    """
  end

  defp parse_providers(nil), do: []

  defp parse_providers(csv) do
    csv
    |> to_string()
    |> String.split(",", trim: true)
    |> Enum.map(&String.to_atom(String.trim(&1)))
    |> Enum.uniq()
  end

  defp camel(snake) do
    snake
    |> to_string()
    |> String.split(~r/[^A-Za-z0-9]+/, trim: true)
    |> Enum.map_join(&String.capitalize/1)
  end

  defp with_goal_warning(igniter, options) do
    if options[:goal] do
      igniter
    else
      Igniter.add_warning(igniter, "consider passing --goal so the scaffold has a real goal")
    end
  end
end
